INSERT INTO stories ("id", "name", "logo_url", "industry", "challenge", "solution", "metrics", "sort", "active") VALUES ('s1', '360 Շինբազա', NULL, '{"am":"Շինանյութ","en":"Building materials","ru":"Стройматериалы"}'::jsonb, '{"am":"Դանդաղ, ձեռքով պատվերների մշակում խանութներում։","en":"Slow, manual order processing across stores.","ru":"Медленная ручная обработка заказов в магазинах."}'::jsonb, '{"am":"Ներդրվեցին BC Վաճառք և Պահեստ մոդուլները։","en":"Deployed BC Sales and Warehouse modules.","ru":"Внедрены модули BC Продажи и Склад."}'::jsonb, '[{"label":{"am":"Ավելի արագ պատվերների մշակում","en":"Faster order processing","ru":"Быстрее обработка заказов"},"suffix":"%","target":50,"decimals":0},{"label":{"am":"Վաճառքի ավելի մեծ տեսանելիություն","en":"More sales visibility","ru":"Больше прозрачности продаж"},"suffix":"%","target":30,"decimals":0}]'::jsonb, 1, true) ON CONFLICT (id) DO NOTHING;
INSERT INTO stories ("id", "name", "logo_url", "industry", "challenge", "solution", "metrics", "sort", "active") VALUES ('s2', 'Արպանիվ', NULL, '{"am":"Դիստրիբյուցիա","en":"Distribution","ru":"Дистрибуция"}'::jsonb, '{"am":"Հաճախակի պաշարի սպառում և ավելցուկ։","en":"Frequent stockouts and excess inventory.","ru":"Частые дефициты и избыток запасов."}'::jsonb, '{"am":"Կենտրոնացված պաշարներ BC Պահեստով։","en":"Centralized inventory with BC Warehouse.","ru":"Централизованные запасы с BC Склад."}'::jsonb, '[{"label":{"am":"Պաշարների օպտիմալացում","en":"Inventory optimization","ru":"Оптимизация запасов"},"suffix":"%","target":35,"decimals":0},{"label":{"am":"Ավելի քիչ պակասորդ","en":"Fewer stockouts","ru":"Меньше дефицита"},"suffix":"%","target":25,"decimals":0}]'::jsonb, 2, true) ON CONFLICT (id) DO NOTHING;
INSERT INTO stories ("id", "name", "logo_url", "industry", "challenge", "solution", "metrics", "sort", "active") VALUES ('s3', 'Կոմպլեքս-Բար', NULL, '{"am":"Մեծածախ","en":"Wholesale","ru":"Опт"}'::jsonb, '{"am":"Ձեռքով տվյալների մուտքագրում և դանդաղ գույքագրում։","en":"Heavy manual data entry and slow inventory counts.","ru":"Ручной ввод данных и медленная инвентаризация."}'::jsonb, '{"am":"Վաճառքի և պահեստի ավտոմատացում BC-ով՝ ScanIt շտրիխ-կոդով հաշվառմամբ։","en":"Automated sales and storage with BC and ScanIt barcode scanning.","ru":"Автоматизация продаж и склада с BC и сканированием штрих-кодов ScanIt."}'::jsonb, '[{"label":{"am":"Ավելի քիչ ձեռքով աշխատանք","en":"Less manual work","ru":"Меньше ручного труда"},"suffix":"%","target":40,"decimals":0},{"label":{"am":"Տվյալների ճշգրտություն","en":"Data accuracy","ru":"Точность данных"},"suffix":"%","target":99.9,"decimals":1}]'::jsonb, 3, true) ON CONFLICT (id) DO NOTHING;
